command:example.dev:code:
# Define the SNMPv3 auth protocol and levels
$CiscoSanManagerSnmpUserName = "ssh-user-SHA-AES128"
$CiscoSanManagerSnmpAuthLevel = "AuthAndPriv"
$CiscoSanManagerSnmpAuthProtocol = "SHA"
$CiscoSanManagerSnmpPrivProtocol = "aes-128"
$CiscoSanManagerSnmpAuthPassword = ConvertTo-SecureString -String "MyPassword" -AsPlainText -Force
$CiscoSanManagerSnmpPrivPassword = ConvertTo-SecureString -String "MyPassword" -AsPlainText -Force

# Define the parameters for the two SAN fabric switches to add
$Params = @(@{

    Hostname         = "172.18.20.1";
    Type             = "Cisco";
    SnmpUsername     = $CiscoSanManagerSnmpUserName;
    SnmpAuthLevel    = $CiscoSanManagerSnmpAuthLevel;
    SnmpAuthProtocol = $CiscoSanManagerSnmpAuthProtocol;
    SnmpAuthPassword = $CiscoSanManagerSnmpAuthPassword;
    SnmpPrivProtocol = $CiscoSanManagerSnmpPrivProtocol; 
    SnmpPrivPassword = $CiscoSanManagerSnmpPrivPassword

}, @{

    Hostname         = "172.18.20.2";
    Type             = "Cisco";
    SnmpUsername     = $CiscoSanManagerSnmpUserName;
    SnmpAuthLevel    = $CiscoSanManagerSnmpAuthLevel;
    SnmpAuthProtocol = $CiscoSanManagerSnmpAuthProtocol;
    SnmpAuthPassword = $CiscoSanManagerSnmpAuthPassword;
    SnmpPrivProtocol = $CiscoSanManagerSnmpPrivProtocol; 
    SnmpPrivPassword = $CiscoSanManagerSnmpPrivPassword

})    

# Add the SAN fabric switches as SAN managers
$Params | % { Add-OVSanManager @_ | Wait-OVTaskComplete }

maml:description.maml:para:
Specify the StoreVirtual or Nimble VIP(s) and associated Ethernet Network. 

Example:

    @{"10.158.11.42" = $EthernetNetwork}

or

    @{"10.158.11.42" = $EthernetNetwork1; "10.158.12.42" = $EthernetNetwork2;}

Specify the StoreVirtual or Nimble VIP(s) and associated Ethernet Network. 

Example:

    @{"10.158.11.42" = $EthernetNetwork}

or

    @{"10.158.11.42" = $EthernetNetwork1; "10.158.12.42" = $EthernetNetwork2;}

command:example.dev:code:
$StorageSystemPorts = @{"1:1:1" = "Fabric A"; "2:1:1" = "Fabric A"; "1:1:2" = "Fabric B"; "2:1:2" = "Fabric B"}
$StoragePortGroups = @{"1:1:1"= "PG1";  "2:1:1" = "PG1"; "1:1:2" = "PG2"; "2:1:2" = "PG2"}
Add-OVStorageSystem -hostname "3par-array.consoto.com" -username 3paradm -password 3pardata -Domain VirtaulDomain1 -Ports $StorageSystemPorts -PortGroups $StoragePortGroups | Wait-OVTaskComplete

$LogicalInterconnect = Get-OVLogicalInterconnect -Name "Encl1-Default VC FF LIG" $MonitoredPorts = @( @{Port = "Enclosure1:Bay3:D2"; Direction = "MonitoredToServer"}, @{Port = "Enclosure1:Bay3:D3"; Direction = "MonitoredFromServer"}, @{Port = "Enclosure2:Bay6:D7"; Direction = "Both"}
)
Enable-OVLogicalInterconnectPortMonitoring -InputObject $LogicalInterconnect -AnalyzerPort "Enclosure1:Bay3:Q1.1" -MonitoredPorts $MonitoredPorts

$UplinkSetName           = "RSPAN Analyzer"
$UplinkSetPort           = "Enclosure1:Bay3:Q6.1"
$LogicalInterconnectName = "Encl1-Default VC FF LIG"
$RSPANNetworkName        = "RSPAN Network"
$RSPANNetworkVlanID      = "411"

If (-not ($RSPANNetwork = Get-OVNetwork -Name $RSPANNetworkName -Type Ethernet -ErrorAction SilentlyContinue)) {

    New-OVNetwork -Name $RSPANNetworkName -VlanID $RSPANNetworkVlanID

}

# Get the logical interconnect resource
$LogicalInterconnect      = Get-OVLogicalInterconnect -Name $LogicalInterconnectName -ErrorAction Stop

# Get the associated logical interconnect group resource from the logical interconnect
$LogicalInterconnectGroup = Get-OVLogicalInterconnectGroup -InputObject $LogicalInterconnect

# Add a new uplink set to the LIG associated with the LI
$UplinkSetParams = @{

    InputObject = $LogicalInterconnectGroup;
    Name        = $UplinkSetName;
    Type        = 'Ethernet';
    Networks    = $RSPANNetwork;
    UplinkPorts = $UplinkSetPort

}

# Create the new uplink set to the logical interconnect group
New-OVUplinkSet @UplinkSetParams

# Update the LI from parent
Update-OVLogicalInterconnect -InputObject $LogicalInterconnect

# Configure port monitoring with the new uplink set configuration
$MonitoredPorts      = @(
    @{Port = "Enclosure1:Bay3:D2"; Direction = "MonitoredToServer"}, 
    @{Port = "Enclosure1:Bay3:D3"; Direction = "MonitoredFromServer"}, 
    @{Port = "Enclosure2:Bay6:D7"; Direction = "Both"} 

)

Enable-OVLogicalInterconnectPortMonitoring -InputObject $LogicalInterconnect -UplinkSetName $UplinkSetName -MonitoredPorts $MonitoredPorts

