command:example.dev:code:
$Name = "HP ProLiant BL460 Gen9 Profile Template"
$con1 = Get-OVNetwork -Name "Net 41-A"  | New-OVServerProfileConnection -connectionId 1
$con2 = Get-OVNetwork -Name "Net 41-B"  | New-OVServerProfileConnection -connectionId 2
$bl460SHT = Get-OVServerHardwareTypes -name "BL460c Gen9 1"
$eg = Get-OVEnclosureGroup "Default EG1"
$params = @{
>>    name                = $Name;
>>    serverHardwareType  = $bl460SHT;
>>    enclosureGroup      = $eg;
>>    connections         = $con1, $con2;
>>    ManageBoot          = $True;
>>    BootMode            = "UEFI";
>>    ApplianceConnection = "MyAppliance1.domain.com"
>>}
>>
New-OVServerProfileTemplate @params | Wait-OVTaskComplete

$profileName = "SQL DB Cluster Node Template v1.0"
$bl660SHT = Get-OVServerHardwareTypes -name "BL660c Gen9 1"
#display the BL660 Gen9 BIOS Settings
$bl660SHT.biosSettings
#Set HP Power Profile (ID 210) to Maximum Performance and HP Power Regulator (ID 140) to HP Static High Performance Mode.
$bl660bios = @(@{id=210;value=3},@{id=140;value=3})
$enclosuregroup = Get-OVEnclosureGroup "Production EG1"
$con1 = Get-OVNetwork -Name "Net 41-A" | New-OVServerProfileConnection -connectionId 1
$con2 = Get-OVNetwork -Name "Net 41-B" | New-OVServerProfileConnection -connectionId 2
$con3 = Get-OVNetwork -Name "fabric a"  | New-OVServerProfileConnection -id 3 -type FibreChannel -bootable -priority Primary -arrayWWPn "21:11:00:02:AC:00:72:03" -LUN 0
$con4 = Get-OVNetwork -Name "fabric b"  | New-OVServerProfileConnection -id 4 -type FibreChannel -bootable -priority Secondary -arrayWWPn "22:12:00:02:AC:00:72:03" -LUN 0
$LogicalDisk = New-OVServerProfileLogicalDisk -Name "My Local Disk" -RAID RAID1 -NumberofDrives 2 -DiskType SasSsd 
$volume1 = Get-OVStorageVolume SharedVolume1  | New-OVServerProfileAttachVolume
$params = @{
>>    name                = $profileName;
>>    connections         = $con1, $con2, $con3, $con4;
>>    bios                = $true;
>>    biossettings        = $bl660bios
>>    manageboot          = $True;
>>    bootMode            = "UEFI";
>>    pxeBootPolicy       = "IPv4ThenIPv6";
>>    bootOrder           = "HardDisk";
>>    HideUnusedFlexnics  = $True;
>>    LocalStorage        = $True;
>>    LogicalDisk         = $LogicalDisk;
>>    SANStorage          = $True;
>>    Ostype              = "Win2k12";
>>    StorageVolume       = $volume1;
}
>>    
New-OVServerProfileTemplate @params | Wait-OVTaskComplete

$ROCENet           = Get-OVNetwork -Name ROCE-Net1
$lig               = Get-OVLogicalInterconnectGroup -Name "LE1-Default Ethernet LIG"
$ROCEUplinkPorts   = "Enclosure1:Bay3:Q3","Enclosure2:Bay6:Q3"
$ROCEUplinkSetName = "ROCE_US1"

$UplinkSetParams = @{

    InputObject  = $lig;
    Name         = $ROCEUplinkSetName;
    Type         = "Ethernet";
    Networks     = $ROCENet;
    UplinkPorts  = $ROCEUplinkPorts
    DCBxOverride = $true;
    ROCEVersion  = "ROCEV2"

}

New-OVUplinkSet @UplinkSetParams

maml:description.maml:para:
Single object returned from appliance

     If Async task, a Hashtable is returned with the following contents:

         @{
             uri = TaskUri;
             category = "tasks";
             type = "TaskResourceV2";
             taskState = "New";
             resource = @{};
         }

If no resources are found, a PsCustomObject is returned that contains:

         @{
             statusCode = [int]HTTP Status Code;
             statusMessage = [string]HTTP Status Message;
             lastCall = [string]URI;
         }

command:example.dev:code:
$NewDCParams = @{

Name             = "Houston DC1";
    Width            = 10668;
    Depth            = 13716;
    Millimeters      = $True;
    DefaultVoltage   = 240e;
    PowerCosts       = 0.10;
    CoolingCapacity  = 350;
    Address1         = "123 Main Place";
    Address2         = "Suite 400";
    City             = "Houston;
    State            = "TX";
    Country          = "US";
    PostCode         = "77002";
    TimeZone         = "US/Central";
    PrimaryContact   = (Get-OVRemoteSupportContact -Name "Joe Ellis" -EA Stop)
    SecondaryContact = (Get-OVRemoteSupportContact -Name "Brandon Pear" -EA Stop)

}
New-OVDataCenter @NewDC2Params

$RackManager = Get-OVRackManager -Name rackmanager1.domain.com -ErrorAction Stop $Credential = Get-Credential Administrator -Message "Password"     $RefreshParams = @{ InputObject = $RackManager} 
# Check the rack manager for its state and refresh state reason if ($RackManager.State -eq 'Unmanaged' -and $RackManager.RefreshState -eq 'RefreshFailed') {     # Add the "Credential" parameter to the Hashtable splat     $RackManager.Add("Credential", $Credential) 
    # Add the Hostname to the Hashtable splat     $RackManager.Add("Hostname", $RackManager.SubResources.Managers[0].Hostname) } Update-OVRackManager @RefreshParams

# Get the latest firmware bundles from HPE
$FirmwareBundleUpdates = Get-OVFirmwareBundleUpdate -GetLatestUpdates

# Get all of the HPE ProLiant DL380 Gen11 servers from inventory
$Servers = Get-OVServer -Query "shortModel:'DL380 Gen11'"

# Use the most current
$Baseline = $FirmwareBundleUpdates | ? bundleGeneration -contains "Gen11" | Sort -Property version -Descending | Select -First 1

# If there is a patch available, use the most recent version
if ($Baseline.Supplements.Count -gt 0) {
    $Servers | Update-OVServerFirmware -Baseline $Baseline -PatchLevel ($Baseline.Supplements | Sort -Descending | Select -First 1)
} else {
    $Servers | Update-OVServerFirmware -Baseline $Baseline
}
